CREATE OR REPLACE PROCEDURE get_employee (p_id bigint, p_name INOUT text) AS $body$
BEGIN
    SELECT name INTO STRICT p_name FROM dev_user.employees WHERE id = p_id;
END;
$body$
LANGUAGE PLPGSQL
